import { createSyncOnceRunner, falseValue, forEach, isSSR, trueValue } from "@alova/shared";
import { onDestroy, onMount } from "svelte";
import { derived, writable } from "svelte/store";
//#region src/statesHook/svelte.ts
var svelte_default = {
	name: "Svelte",
	create: (data) => writable(data),
	dehydrate: (state) => {
		let raw;
		state.subscribe((value) => {
			raw = value;
		})();
		return raw;
	},
	update: (newVal, state) => {
		state.set(newVal);
	},
	effectRequest({ handler, immediate, watchingStates }) {
		onMount(() => {
			immediate && handler();
		});
		forEach(watchingStates || [], (state, i) => {
			let needEmit = falseValue;
			state.subscribe(() => {
				needEmit ? handler(i) : needEmit = trueValue;
			});
		});
	},
	computed: (getter, depList) => derived(depList, getter),
	watch: (states, callback) => {
		let needEmit = falseValue;
		const syncRunner = createSyncOnceRunner();
		states.forEach((state) => {
			state.subscribe(() => {
				syncRunner(() => {
					needEmit ? callback() : needEmit = trueValue;
				});
			});
		});
	},
	onMounted: (callback) => {
		onMount(callback);
	},
	onUnmounted: (callback) => {
		!isSSR && onDestroy(callback);
	}
};
//#endregion
export { svelte_default as default };
